package id.imperial.resourcepack.velocity;
import com.velocitypowered.api.command.SimpleCommand;import id.imperial.resourcepack.common.*;import net.kyori.adventure.text.Component;
final class VelocityCommand implements SimpleCommand {private final ImperialResourcePackVelocity p;VelocityCommand(ImperialResourcePackVelocity p){this.p=p;}public void execute(Invocation i){if(!i.source().hasPermission("imperialresourcepack.admin")){say(i,"No permission.");return;}String a=i.arguments().length==0?"status":i.arguments()[0];if(a.equalsIgnoreCase("reload"))say(i,p.reload());else if(a.equalsIgnoreCase("validate")){var r=p.manager().validateActive(p.config());say(i,r.message());}else if(a.equalsIgnoreCase("info")||a.equalsIgnoreCase("status")){ActivePack x=p.manager().active();say(i,x==null?"No active pack.":x.file().getFileName()+" | SHA-1: "+x.sha1Hex()+" | UUID: "+x.id()+" | HTTP: "+p.host().running());}else say(i,"Usage: /irp <reload|status|validate|info>");}private void say(Invocation i,String s){i.source().sendMessage(Component.text("[IRP] "+s));}}
